SELECT T1.FINPROD_MARKET_ID, T1.FINPROD_ID FROM FIN_PRODUCT T1 INNER join FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID and T2.IS_AUTO_UPDATE ='Y'
T1.FINPROD_MARKET_ID in
#{item}

select SECID, SCHEDUTYPE, TOTALINTERESTSTARTDAY, TOTALINTERESTENDDAY, INTERESTSTARTDAY, INTERESTENDDAY, INTERESTPAYDAY, COUPONRATE, ACCRUEINTAMT, DAILYACCRUEINT, PRINAMTPAY, CASHPAY, PRINAMT, SOURCE from INTERF_PAYHSRCSECSCHEDULE where SECID = #{secid,jdbcType=VARCHAR}
AND INTERESTSTARTDAY >= #{maxTradeDate,jdbcType=VARCHAR}
ORDER BY INTERESTPAYDAY ASC
